import { defineConfig, devices, type Project } from '@playwright/test';
import { defineBddConfig } from 'playwright-bdd';
import { env } from './src/config/env';

/*
 * Projects
 *   api          - contract/negative tests against the public Automation Exercise API (no browser)
 *   integration  - payment, webhook, calendar and e-mail tests against local simulated services
 *   chromium     - UI tests (POM + Screenplay) against the public demo shop
 *   bdd          - Gherkin scenarios generated by playwright-bdd into .features-gen/
 *   firefox/webkit - opt-in cross-browser UI runs (CROSS_BROWSER=true)
 */

const bddTestDir = defineBddConfig({
  features: 'features/**/*.feature',
  steps: 'features/steps/**/*.ts',
  outputDir: '.features-gen',
});

// CI runs several stages (api, smoke, regression); TEST_SUITE keeps their reports apart.
const reportRoot = process.env.TEST_SUITE ? `reports/${process.env.TEST_SUITE}` : 'reports';

const uiProjects: Project[] = [{ name: 'chromium', use: { ...devices['Desktop Chrome'] } }];
if (env.CROSS_BROWSER) {
  uiProjects.push(
    { name: 'firefox', use: { ...devices['Desktop Firefox'] } },
    { name: 'webkit', use: { ...devices['Desktop Safari'] } },
  );
}

export default defineConfig({
  timeout: 60_000,
  expect: { timeout: 10_000 },
  fullyParallel: true,
  forbidOnly: env.CI,
  // One retry on CI absorbs infrastructure blips on the public site. Flaky results are still
  // reported as "flaky" in HTML/JUnit, and local-service projects override this to 0.
  retries: env.CI ? 1 : 0,
  // The public demo shop rate-limits aggressively; more workers mostly produce "queue full" pages.
  // Override with --workers=N.
  workers: 3,
  outputDir: process.env.TEST_SUITE ? `test-results/${process.env.TEST_SUITE}` : 'test-results',
  reporter: [
    ['list'],
    ['html', { outputFolder: `${reportRoot}/html`, open: 'never' }],
    ['junit', { outputFile: `${reportRoot}/junit/results.xml` }],
    ...(env.CI ? ([['github']] as const) : []),
  ],
  use: {
    baseURL: env.BASE_URL,
    testIdAttribute: 'data-qa',
    trace: 'retain-on-failure',
    screenshot: 'only-on-failure',
    video: 'retain-on-failure',
    actionTimeout: 15_000,
    navigationTimeout: 30_000,
  },
  projects: [
    { name: 'api', testDir: 'tests/api' },
    // Deterministic local services: any failure is real, so retries would only hide defects.
    { name: 'integration', testDir: 'tests/integration', retries: 0 },
    ...uiProjects.map((p) => ({ ...p, testDir: 'tests/ui' })),
    { name: 'bdd', testDir: bddTestDir, use: { ...devices['Desktop Chrome'] } },
  ],
  webServer: [
    {
      name: 'mailpit',
      command: '.tools/mailpit/mailpit --smtp 127.0.0.1:1025 --listen 127.0.0.1:8025',
      url: `${env.MAILPIT_URL}/readyz`,
      reuseExistingServer: true,
      timeout: 30_000,
      stdout: 'ignore',
    },
    {
      name: 'services',
      command: 'npx tsx services/start-services.ts',
      url: `${env.PAYMENT_SERVICE_URL}/health`,
      reuseExistingServer: true,
      timeout: 30_000,
    },
  ],
});
